#pragma once
#include <cstdint>
#include <tuple>
#include <type_traits>
namespace mspa {
template <typename Tag,typename Rep=std::uint64_t> class StrongId{public:using rep_type=Rep;constexpr StrongId()noexcept=default;explicit constexpr StrongId(Rep v)noexcept:value_(v){}[[nodiscard]]constexpr Rep value()const noexcept{return value_;}[[nodiscard]]constexpr bool valid()const noexcept{return value_!=Rep{};}friend constexpr bool operator==(StrongId a,StrongId b)noexcept{return a.value_==b.value_;}friend constexpr bool operator!=(StrongId a,StrongId b)noexcept{return !(a==b);}friend constexpr bool operator<(StrongId a,StrongId b)noexcept{return a.value_<b.value_;}private:Rep value_{};};
struct RuntimeIdTag;struct WorldIdTag;struct NamespaceIdTag;struct ConceptIdTag;struct PredicateIdTag;struct StimulusIdTag;struct GoalIdTag;struct BeliefIdTag;struct MemoryIdTag;struct ActionTypeIdTag;struct ActionInstanceIdTag;struct ActionContinuityKeyTag;struct PackIdTag;struct TimeDomainIdTag;struct ProfileIdTag;
using RuntimeId=StrongId<RuntimeIdTag>;using WorldId=StrongId<WorldIdTag>;using NamespaceId=StrongId<NamespaceIdTag>;using ConceptId=StrongId<ConceptIdTag>;using PredicateId=StrongId<PredicateIdTag>;using StimulusId=StrongId<StimulusIdTag>;using GoalId=StrongId<GoalIdTag>;using BeliefId=StrongId<BeliefIdTag>;using MemoryId=StrongId<MemoryIdTag>;using ActionTypeId=StrongId<ActionTypeIdTag>;using ActionInstanceId=StrongId<ActionInstanceIdTag>;using ActionContinuityKey=StrongId<ActionContinuityKeyTag>;using PackId=StrongId<PackIdTag>;using TimeDomainId=StrongId<TimeDomainIdTag>;using ProfileId=StrongId<ProfileIdTag>;
struct AgentId{WorldId world{};std::uint64_t local_id{};[[nodiscard]]constexpr bool valid()const noexcept{return world.valid()&&local_id!=0;}friend constexpr bool operator==(const AgentId&a,const AgentId&b)noexcept{return a.world==b.world&&a.local_id==b.local_id;}friend constexpr bool operator!=(const AgentId&a,const AgentId&b)noexcept{return !(a==b);}friend constexpr bool operator<(const AgentId&a,const AgentId&b)noexcept{return std::tie(a.world,a.local_id)<std::tie(b.world,b.local_id);}};
static_assert(!std::is_convertible_v<WorldId,RuntimeId>,"Strong IDs must not be implicitly interchangeable");
}
